#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Generate src/verification/oracle/fft/twiddle_table.inc.

The FFT specification (src/workloads/fft/spec.hpp, "THE TWIDDLE TABLE") defines
W[m] = (RN(cos(2 pi m / n)), RN(-sin(2 pi m / n))) for m in [0, n), n = 4096,
where RN(a) is the double nearest the REAL number a, with an exact zero written
+0.0. This script evaluates the cosine and the sine to 100 decimal digits with
mpmath, turns the value into an exact rational, and lets Python's correctly
rounded int/int division pick the nearest double. The multiples of n/4, where a
cosine or a sine is exactly 0 or +-1, are written down rather than computed.

Run from the repository root:

    python3 tests/fixtures/verification/oracle/fft/generate_twiddles.py \
        > src/verification/oracle/fft/twiddle_table.inc

The output is the initializer list of kTwiddleBits, included by twiddle.cpp; it
is a list of numbers and not a translation unit, so that the coverage gate's
requirement that every .cpp of src/ appear in its report is met by the accessor
that follows the table and not by a data file with nothing to execute.

The committed table was produced with Python 3.13.16 and mpmath 1.4.1 on an
x86-64 Linux machine (Intel Xeon 2.10GHz, kernel 6.18.44). The result does not
depend on the machine: every step is exact integer arithmetic or a correctly
rounded division, and the test that checks the table (tests/unit/verification/
oracle/fft) does so against the C library's long double sine and cosine, not
against this script.
"""

import struct
import sys
from fractions import Fraction

from mpmath import cos, mp, mpf, pi, sin

POINTS = 4096
SQRT_HALF_BITS = 0x3FE6A09E667F3BCD


def nearest_double(value) -> float:
    """The double nearest the real number `value` (a 100-digit mpf)."""
    scaled = int(value * mpf(2) ** 400)
    return float(Fraction(scaled, 2**400))


def bits(value: float) -> int:
    return int.from_bytes(struct.pack("<d", value), "little")


def twiddle(m: int) -> tuple[float, float]:
    quarter = POINTS // 4
    if m % quarter == 0:
        return {
            0: (1.0, 0.0),
            1: (0.0, -1.0),
            2: (-1.0, 0.0),
            3: (0.0, 1.0),
        }[m // quarter]
    angle = 2 * pi * m / POINTS
    return nearest_double(cos(angle)), nearest_double(-sin(angle))


def main() -> None:
    mp.dps = 100
    table = [twiddle(m) for m in range(POINTS)]
    assert bits(table[POINTS // 8][0]) == SQRT_HALF_BITS
    assert table[POINTS // 8][1] == -table[POINTS // 8][0]
    words = [bits(part) for pair in table for part in pair]

    out = sys.stdout
    out.write("// SPDX-License-Identifier: GPL-3.0-or-later\n")
    out.write("//\n")
    out.write("// GENERATED by tests/fixtures/verification/oracle/fft/generate_twiddles.py;\n")
    out.write("// do not edit. The twiddle table of the FFT specification: for m in [0, 4096),\n")
    out.write("// the bits of Re W[m] then Im W[m], each the double nearest the real number\n")
    out.write("// cos(2 pi m / 4096) and -sin(2 pi m / 4096), an exact zero as +0.0.\n")
    for start in range(0, len(words), 4):
        out.write("".join(f"0x{word:016X}ULL, " for word in words[start : start + 4]).rstrip())
        out.write("\n")


if __name__ == "__main__":
    main()
